Lemma KS2_granted : forall st n a, 0 < a_ptr_array st + 8 * a_nres st -> a_ptr_array st + 8 * a_nres st + 131072 <= ATOP ->
  KS2 st n a (a_ptr_array st + 8 * a_nres st)
